apiVersion: apps/v1
kind: Deployment
metadata:
  name: vuoro-shared
  namespace: vuoro-shared
  labels: {app.kubernetes.io/name: vuoro-shared}
  annotations:
    appservice.kotona.app/release: vuoro-service-v0.1.95
    appservice.kotona.app/image-digest: sha256:b3e4097fb9e30e956d136cbe9046ac163a0549c508f690c149b885989a63f2ad
spec:
  # vuoro-service 0.1.61+ binds only the work and audit domains (S2 item 4).
  replicas: 1
  selector: {matchLabels: {app.kubernetes.io/name: vuoro-shared}}
  template:
    metadata:
      labels: {app.kubernetes.io/name: vuoro-shared}
      annotations:
        # Reload the registry for scoped MI-1 and inbox identities.
        vuoro.kotona.app/identity-revision: "12"
    spec:
      securityContext: {runAsNonRoot: true, runAsUser: 65532, seccompProfile: {type: RuntimeDefault}}
      containers:
        - name: service
          image: ghcr.io/bayleafwalker/vuoro-service@sha256:b3e4097fb9e30e956d136cbe9046ac163a0549c508f690c149b885989a63f2ad
          ports: [{name: http, containerPort: 8080}]
          # PodSecurity restricted:latest.
          securityContext: {allowPrivilegeEscalation: false, capabilities: {drop: [ALL]}}
          envFrom: [{configMapRef: {name: vuoro-shared-config}}]
          env:
            - {name: VUORO_IDENTITIES_FILE, value: /run/vuoro/identities.json}
            - {name: VUORO_WORK_RESOURCE_OBSERVERS_FILE, value: /run/vuoro-observers/policy.json}
            - {name: VUORO_WORK_RUNTIME_DSN, valueFrom: {secretKeyRef: {name: vuoro-work-runtime, key: uri}}}
            - {name: VUORO_AUDIT_RUNTIME_DSN, valueFrom: {secretKeyRef: {name: vuoro-audit-runtime, key: uri}}}
          volumeMounts:
            - {name: identities, mountPath: /run/vuoro, readOnly: true}
            - {name: work-resource-observers, mountPath: /run/vuoro-observers, readOnly: true}
          readinessProbe: {httpGet: {path: /health/ready, port: http}, timeoutSeconds: 7}
          livenessProbe: {httpGet: {path: /health/live, port: http}, timeoutSeconds: 7}
      volumes:
        - {name: identities, secret: {secretName: vuoro-identities}}
        - {name: work-resource-observers, configMap: {name: vuoro-work-resource-observers}}
